query getEventContent($eventId: ID!, $offset: Int) {
  node(id: $eventId) {
    ... on Event {
      content(
        offset: $offset
        order: {field: order, direction: asc}
        filters: [{field: isArchived, operation: eq, value: "false"}, {field: isHidden, operation: eq, value: "false"}, { field: type, operation: eq, value: "scorm" }]
      ) {
        pageInfo {
          hasNextPage
          endCursor
        }
        edges {
          node {
            id
          }
        }
      }
    }
  }
}

mutation AttemptScorm($learnerId: ID!, $contentId: ID!) {
  learner {
    attemptScorm(input: { learnerId: $learnerId, contentId: $contentId }) {
      errors {
        label
        message
        value
      }
      learner {
        lmsProgress
        contact {
          name
          id
        }
        contentResults {
          edges {
            node {
              contentId
              progress
            }
          }
        }
      }
    }
  }
}

mutation AdminCompleteScorm($learnerId: ID!, $contentId: ID!) {
  learner {
    adminCompleteScorm(input: { learnerId: $learnerId, contentId: $contentId }) {
      errors {
        label
        message
        value
      }
      learner {
        lmsProgress
        contact {
          name
          id
        }
        contentResults {
          edges {
            node {
              contentId
              progress
            }
          }
        }
      }
    }
  }
}

query getLearnersResults(
    $offset: Int!
    $limit: Int!
    $filters: [LearnerFieldGraphFilter]!
    $overrideLocator: String
) {
    learners(
        offset: $offset
        first: $limit
        filters: $filters
        order: { field: contactName, direction: asc }
    ) {
        edges {
            node {
                id
                contactId
                customFieldValues(filter: { definitionLocator: $overrideLocator }) {
                    definitionLocator
                    value
                }
            }
        }
        pageInfo {
            hasNextPage
            hasPreviousPage
            startCursor
            endCursor
            totalRecords
        }
    }
}

query webhookQuery($objectid: ID!) {
    node(id: $objectid) {
        id
        ... on Event {
            id
            legacyId
        }
    }
}

