// Administrate returns HTTP 200 even when a mutation is rejected, so both nested
// errors arrays are checked. A request that fails outright arrives as an empty item
// (the mutation nodes continue on error and always output data).
const pair = $('Loop Over Items').first().json;
const attempt = $('Attempt SCORM').first().json?.learner?.attemptScorm;
const complete = $input.first().json?.learner?.adminCompleteScorm;

const describe = (errors) => (errors || []).map(e => e.message || e.label).filter(Boolean).join('; ');
const attemptErrors = attempt ? describe(attempt.errors) : 'no response returned';
const completeErrors = complete ? describe(complete.errors) : 'no response returned';

let status = 'completed';
let reason = 'SCORM content marked as complete';

if (completeErrors) {
  status = 'error';
  reason = `Completing failed: ${completeErrors}`;
  if (attemptErrors) {
    reason = `Attempt failed: ${attemptErrors}. ${reason}`;
  }
} else if (attemptErrors) {
  status = 'warning';
  reason = `Completed, but the attempt returned: ${attemptErrors}`;
}

return [{ json: {
  learnerId: pair.learnerId,
  contentId: pair.contentId,
  learnerName: complete?.learner?.contact?.name ?? attempt?.learner?.contact?.name ?? '',
  status,
  reason
} }];

const results = $input.all().map(item => item.json);

const completed = results.filter(r => r.status === 'completed');
const warnings = results.filter(r => r.status === 'warning');
const failures = results.filter(r => r.status === 'error');

const line = (r) => `- ${r.learnerName || r.learnerId} / ${r.contentId}: ${r.reason}`;

const summary = [
  `Completed: ${completed.length}`,
  `Completed with warnings: ${warnings.length}`,
  `Failed: ${failures.length}`,
  ...(warnings.length ? ['', 'Warnings:', ...warnings.map(line)] : []),
  ...(failures.length ? ['', 'Failures:', ...failures.map(line)] : [])
].join('\n');

return [{ json: {
  eventId: $('Config').first().json.EVENT_ID,
  completedCount: completed.length,
  warningCount: warnings.length,
  errorCount: failures.length,
  warnings,
  failures,
  summary
} }];
